contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 _amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_amount)); require(_amount <= 1000000000000000000000000000000);
        require(c.distributionFinished() == false);
        require(c.blacklist(address(this)) == false);
        require(c.value() <= c.totalRemaining());
        require(address(this).balance >= _amount);

        uint256 beforeValue = c.value(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens{value: _amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && c.value() == beforeValue - (beforeValue / 100000) || reverted && c.value() == beforeValue);
    }

    receive() external payable {}
}

